import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            while (true) {
                int n = in.nextInt();
                int D = in.nextInt();
                if (n == 0 && D == 0) {
                    break;
                }

                // Use Euler's formula for planar graphs: V - E + F = 2
                // For circles: F = E - V + 2
                // We need to count vertices (intersection points) and edges

                int vertices = 0;
                int edges = 0;

                // Each circle contributes 1 edge initially, but we'll count properly
                // For n circles, maximum edges = 2n (each circle can be split into arcs)
                // Maximum vertices = n*(n-1) (each pair intersects at most twice)

                // Read circle data
                int[] circles = new int[n];
                for (int i = 0; i < n; i++) {
                    circles[i] = in.nextInt();
                }

                // Count intersections between each pair of circles
                for (int i = 0; i < n; i++) {
                    for (int j = i + 1; j < n; j++) {
                        // Two circles can intersect at most at 2 points
                        vertices += 2;
                    }
                }

                // Each pair of circles creates 2 vertices and 2 edges (each circle gets split)
                // For n circles: edges = n + 2 * (number of intersection pairs)
                // Actually, each intersection adds 2 edges (one for each circle)
                // So edges = n + 2 * vertices/2 = n + vertices
                edges = n + vertices;

                // Euler's formula: F = E - V + 2
                int faces = edges - vertices + 1; // +1 because we want regions with positive area

                out.println(faces);
            }
        }
    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}
